def MediumAtom.alphaCarrier (d : MediumAtom) : Finset ℕ :=
  (Finset.Icc (Nat.ceil d.U) (Nat.floor (2 * d.U))).filter
    (fun n => d.intervalLo < (n : ℝ) ∧ (n : ℝ) ≤ d.intervalHi)

def MediumAtom.transposedPairedSWError (d : MediumAtom) (k q b : ℕ) : ℂ :=
  (∑ n ∈ d.transposedAtom.betaCarrier,
    if Nat.ModEq q n b ∧ Nat.Coprime n k then d.transposedAtom.beta n else 0) -
  (∑ n ∈ d.transposedAtom.betaCarrier,
    if Nat.Coprime n (k * q) then d.transposedAtom.beta n else 0) / (Nat.totient q : ℂ)

def MediumAtom.groupedFactorGamma (d : MediumAtom) (q : ℕ) : ℂ :=
  ∑ r ∈ d.physicalFactorFiber q, d.complexFactorGamma r

